CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "idp_id" varchar, "locale" varchar not null default 'en', "sso_logged_out_at" datetime, "is_service" tinyint(1) not null default '0');
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "passkeys" ("id" integer primary key autoincrement not null, "user_id" integer not null, "name" varchar not null, "credential_id" varchar not null, "credential" text not null, "last_used_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "issue_label" ("issue_id" integer not null, "label_id" integer not null, foreign key("issue_id") references "issues"("id") on delete cascade, foreign key("label_id") references "labels"("id") on delete cascade, primary key ("issue_id", "label_id"));
CREATE TABLE "issue_template_label" ("id" integer primary key autoincrement not null, "issue_template_id" integer not null, "label_id" integer not null, foreign key("issue_template_id") references "issue_templates"("id") on delete cascade, foreign key("label_id") references "labels"("id") on delete cascade);
CREATE TABLE "organizations" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "organization_user" ("id" integer primary key autoincrement not null, "organization_id" integer not null, "user_id" integer not null, "role" varchar not null default 'member', "created_at" datetime, "updated_at" datetime, foreign key("organization_id") references "organizations"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "labels" ("id" integer primary key autoincrement not null, "name" varchar not null, "color" varchar not null default ('gray'), "created_at" datetime, "updated_at" datetime, "organization_id" integer, foreign key("organization_id") references organizations("id") on delete cascade on update no action);
CREATE TABLE "project_user" ("id" integer primary key autoincrement not null, "project_id" integer not null, "user_id" integer not null, "level" varchar not null default 'write', "created_at" datetime, "updated_at" datetime, "own_issues_only" tinyint(1) not null default '0', foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("project_id") references projects("id") on delete cascade on update no action);
CREATE TABLE "invitations" ("id" integer primary key autoincrement not null, "project_id" integer, "email" varchar not null, "level" varchar, "token" varchar not null, "invited_by_id" integer, "expires_at" datetime not null, "accepted_at" datetime, "created_at" datetime, "updated_at" datetime, "organization_id" integer, "role" varchar not null default ('member'), foreign key("organization_id") references organizations("id") on delete cascade on update no action, foreign key("project_id") references projects("id") on delete cascade on update no action, foreign key("invited_by_id") references users("id") on delete set null on update no action);
CREATE TABLE "time_entries" ("id" integer primary key autoincrement not null, "issue_id" integer not null, "user_id" integer, "minutes" integer not null, "spent_on" date not null, "note" varchar, "created_at" datetime, "updated_at" datetime, foreign key("issue_id") references "issues"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE "comments" ("id" integer primary key autoincrement not null, "issue_id" integer not null, "user_id" integer, "body" text not null, "created_at" datetime, "updated_at" datetime, "edited_at" datetime, foreign key("issue_id") references "issues"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE "activities" ("id" integer primary key autoincrement not null, "issue_id" integer not null, "user_id" integer, "type" varchar not null, "data" text, "created_at" datetime, "updated_at" datetime, foreign key("issue_id") references "issues"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE "commits" ("id" integer primary key autoincrement not null, "issue_id" integer not null, "repository" varchar not null, "sha" varchar not null, "branch" varchar not null, "message" text not null, "author_name" varchar, "url" varchar, "committed_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("issue_id") references "issues"("id") on delete cascade);
CREATE TABLE "categories" ("id" integer primary key autoincrement not null, "organization_id" integer not null, "parent_id" integer, "name" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("organization_id") references "organizations"("id") on delete cascade, foreign key("parent_id") references "categories"("id") on delete cascade);
CREATE TABLE "notifications" ("id" varchar not null, "type" varchar not null, "notifiable_type" varchar not null, "notifiable_id" integer not null, "data" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "saved_views" ("id" integer primary key autoincrement not null, "user_id" integer not null, "project_id" integer, "name" varchar not null, "criteria" text not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("project_id") references "projects"("id") on delete cascade);
CREATE TABLE "issue_templates" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "type" varchar, "priority" varchar, "created_at" datetime, "updated_at" datetime, "organization_id" integer, "cadence" varchar not null default 'none', "next_run_at" datetime, "target_project_id" integer, foreign key("organization_id") references organizations("id") on delete cascade on update no action, foreign key("target_project_id") references "projects"("id") on delete set null);
CREATE TABLE "project_types" ("id" integer primary key autoincrement not null, "organization_id" integer, "name" varchar not null, "description" text, "is_default" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("organization_id") references "organizations"("id") on delete cascade);
CREATE TABLE "workflow_states" ("id" integer primary key autoincrement not null, "project_type_id" integer not null, "name" varchar not null, "category" varchar not null, "color" varchar not null, "position" integer not null default '0', "is_default" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("project_type_id") references "project_types"("id") on delete cascade);
CREATE TABLE "issues" ("id" integer primary key autoincrement not null, "project_id" integer not null, "number" integer not null, "identifier" varchar not null, "title" varchar not null, "slug" varchar not null, "description" text, "type" varchar not null, "status" varchar not null default ('backlog'), "branch_name" varchar not null, "github_pr_url" varchar, "closed_at" datetime, "created_at" datetime, "updated_at" datetime, "archived_at" datetime, "priority" varchar not null default ('none'), "parent_id" integer, "owner_id" integer, "assignee_id" integer, "estimate_minutes" integer, "archive_reason" varchar, "invoiceable" tinyint(1) not null default ('0'), "confirmed_minutes" integer, "confirmed_at" datetime, "template_id" integer, "workflow_state_id" integer, "source" varchar, "external_ref" varchar, "external_reporter" varchar, "board_position" integer not null default '0', foreign key("template_id") references issue_templates("id") on delete set null on update no action, foreign key("parent_id") references issues("id") on delete set null on update no action, foreign key("project_id") references projects("id") on delete restrict on update no action, foreign key("owner_id") references users("id") on delete set null on update no action, foreign key("assignee_id") references users("id") on delete set null on update no action, foreign key("workflow_state_id") references "workflow_states"("id") on delete set null);
CREATE TABLE "project_webhooks" ("id" integer primary key autoincrement not null, "project_id" integer not null, "url" varchar not null, "secret" varchar not null, "active" tinyint(1) not null default '1', "last_delivered_at" datetime, "last_status" integer, "last_error" varchar, "created_at" datetime, "updated_at" datetime, "events" text, foreign key("project_id") references "projects"("id") on delete cascade);
CREATE TABLE "issue_watchers" ("id" integer primary key autoincrement not null, "issue_id" integer not null, "user_id" integer not null, "watching" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("issue_id") references "issues"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "issue_links" ("id" integer primary key autoincrement not null, "issue_id" integer not null, "related_issue_id" integer not null, "relation" varchar not null, "created_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("issue_id") references "issues"("id") on delete cascade, foreign key("related_issue_id") references "issues"("id") on delete cascade, foreign key("created_by") references "users"("id") on delete set null);
CREATE VIRTUAL TABLE issue_search USING fts5(
            issue_id UNINDEXED,
            identifier,
            title,
            description,
            comments,
            tokenize = "unicode61"
        );
CREATE TABLE "projects" ("id" integer primary key autoincrement not null, "key" varchar not null, "name" varchar not null, "next_number" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "color" varchar not null default ('#6e6d65'), "production_url" varchar, "github_repos" text, "archive_after_days" integer default '7', "description" text, "organization_id" integer, "category_id" integer, "billr_project_id" integer, "billr_client_id" integer, "archived_at" datetime, "project_type_id" integer, "stale_after_days" integer, foreign key("project_type_id") references project_types("id") on delete set null on update no action, foreign key("organization_id") references organizations("id") on delete cascade on update no action, foreign key("category_id") references categories("id") on delete set null on update no action);
